import {config} from './config.js';
export function normalizeUsername(value){const username=String(value).trim().toLowerCase();if(!/^[a-z0-9][a-z0-9_-]{3,23}$/.test(username))throw Error('아이디는 영문 소문자·숫자·밑줄·하이픈으로 4~24자 입력해 주세요.');return username;}
export const usernameEmail=value=>`${normalizeUsername(value)}@students.danbi.invalid`;
const bar=document.createElement('section');bar.className='account-bar';bar.innerHTML='<span id="account-name">계정 연결 확인 중…</span><button id="account-login">로그인 · 가입</button><button id="account-history" hidden>나의 학습 기록</button><button id="account-logout" hidden>로그아웃</button><span id="record-status" role="status" aria-live="polite"></span><button id="record-retry" hidden>저장 다시 시도</button>';
document.querySelector('header').after(bar);
const modal=document.createElement('dialog');modal.className='account-dialog';modal.innerHTML='<button id="account-close" type="button" aria-label="계정 창 닫기">✕</button><h2>나의 역사 탐험 계정</h2><form id="account-form"><label>아이디<input name="username" autocomplete="username" minlength="4" maxlength="24" pattern="[A-Za-z0-9][A-Za-z0-9_-]{3,23}" required></label><label>비밀번호<input name="password" type="password" autocomplete="current-password" minlength="12" maxlength="72" required></label><p>아이디 4~24자 · 비밀번호 12~72자. 이름·학번 대신 별명을 사용해 주세요.</p><button type="submit" class="primary">로그인</button><button type="button" id="account-signup">새 계정 만들기</button><p id="account-message" role="status" aria-live="polite"></p></form><p>비밀번호를 잊으셨나요? <strong>담당 교사에게 문의해 주세요.</strong> 비밀번호를 채팅이나 댓글로 보내지 마세요.</p><p>학습 기록은 본인 계정으로 로그인했을 때만 표시됩니다. 공용 기기에서는 사용 후 로그아웃하세요.</p><div id="account-records"></div>';
document.body.append(modal);
const get=id=>document.getElementById(id);let client,user=null,retry=null,busy=false;
get('account-close').onclick=()=>modal.close();
function notify(s){get('account-message').textContent=s;}
function show(){document.dispatchEvent(new Event('account-dialog-open'));if(!modal.open)modal.showModal();get('account-form').hidden=!!user;get('account-records').replaceChildren();notify('');if(!user)get('account-form').elements.username.focus();else get('account-close').focus();}
get('account-login').onclick=show;
function refresh(next){const changed=user?.id!==next?.id;user=next;get('account-name').textContent=user?normalizeUsername(user.email.split('@')[0])+' 님':'로그인하고 탐험 기록을 모아요';get('account-login').hidden=!!user;get('account-history').hidden=!user;get('account-logout').hidden=!user;if(changed){retry=null;get('record-retry').hidden=true;get('record-status').textContent='';document.dispatchEvent(new Event('account-changed'));}}
export const ready=(async()=>{if(!config.supabaseUrl||!config.supabasePublishableKey){get('account-name').textContent='계정 서버 연결이 아직 준비되지 않았습니다.';return;}try{const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.117.3/+esm');client=createClient(config.supabaseUrl,config.supabasePublishableKey,{auth:{persistSession:false,autoRefreshToken:true,detectSessionInUrl:false}});const {data,error}=await client.auth.getSession();if(error)throw error;refresh(data.session?.user??null);client.auth.onAuthStateChange((_event,session)=>refresh(session?.user??null));}catch{get('account-name').textContent='계정 서버를 연결하지 못했습니다. 새로고침해 주세요.';}})();
async function authenticate(signup){if(busy)return;const form=get('account-form');if(!form.reportValidity())return;busy=true;for(const b of form.querySelectorAll('button'))b.disabled=true;try{await ready;if(!client)throw Error('계정 서버가 준비되지 않았습니다.');const email=usernameEmail(form.elements.username.value),password=form.elements.password.value;const {data,error}=signup?await client.auth.signUp({email,password}):await client.auth.signInWithPassword({email,password});if(error)throw Error(signup?'가입하지 못했습니다. 다른 아이디로 다시 시도하거나 담당 교사에게 문의해 주세요.':'아이디와 비밀번호를 확인해 주세요.');if(!data.session)throw Error('계정 승인 설정을 확인해야 합니다. 담당 교사에게 문의해 주세요.');refresh(data.user);form.reset();modal.close();}catch(e){notify(e.message);}finally{busy=false;for(const b of form.querySelectorAll('button'))b.disabled=false;}}
get('account-form').onsubmit=e=>{e.preventDefault();authenticate(false);};get('account-signup').onclick=()=>authenticate(true);
get('account-logout').onclick=async()=>{const {error}=await client.auth.signOut({scope:'local'});if(error){get('record-status').textContent='로그아웃하지 못했습니다. 다시 시도해 주세요.';return;}refresh(null);};
get('account-history').onclick=async()=>{show();const owner=user?.id;if(!owner)return;get('account-records').textContent='학습 기록을 불러오는 중…';const {data,error}=await client.from('learning_runs').select('created_at,coins,solved,first_try,completed,elapsed_seconds').eq('user_id',owner).order('created_at',{ascending:false}).limit(20);if(user?.id!==owner)return;const list=get('account-records');list.replaceChildren();if(error){list.textContent='기록을 불러오지 못했습니다. 다시 시도해 주세요.';return;}if(!data.length)list.textContent='아직 저장된 탐험이 없어요.';for(const r of data){const p=document.createElement('p');p.textContent=`${new Date(r.created_at).toLocaleString('ko-KR')} · ${r.completed?'완료':'진행 중'} · 역사 문 ${r.solved}/5 · 코인 ${r.coins} · 첫 정답 ${r.first_try}/5`;list.append(p);}};
export async function requireAccount(){await ready;if(user)return true;show();return false;}
export function currentUser(){return user?.id??null;}
let saveQueue=Promise.resolve();
export function saveRun(row){const snapshot={...row};saveQueue=saveQueue.catch(()=>{}).then(async()=>{const owner=user?.id;if(!client||!owner||owner!==snapshot.user_id)return;get('record-status').textContent='학습 기록 저장 중…';try{const {error}=await client.from('learning_runs').upsert(snapshot,{onConflict:'id'});if(error)throw error;if(user?.id!==owner)return;retry=null;get('record-status').textContent='학습 기록을 저장했어요.';get('record-retry').hidden=true;}catch{if(user?.id!==owner)return;retry=snapshot;get('record-status').textContent='기록을 저장하지 못했습니다.';get('record-retry').hidden=false;}});return saveQueue;}
get('record-retry').onclick=()=>{if(retry)saveRun(retry);};
